import matter from "gray-matter";

export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  draft?: boolean;
  layout?: string;
  [key: string]: unknown;
}

export interface ParsedMarkdown {
  frontmatter: Frontmatter;
  content: string;
  raw: string;
}

export function parseFrontmatter(raw: string): ParsedMarkdown {
  const { data, content } = matter(raw);
  const frontmatter = normalizeFrontmatter(data);
  return { frontmatter, content, raw };
}

function normalizeFrontmatter(data: Record<string, unknown>): Frontmatter {
  const fm: Frontmatter = {
    title: typeof data.title === "string" ? data.title : "Untitled",
  };

  if (typeof data.date === "string" || data.date instanceof Date) {
    fm.date = new Date(data.date as string | Date).toISOString();
  }

  if (Array.isArray(data.tags)) {
    fm.tags = data.tags.map((t) => String(t));
  } else if (typeof data.tags === "string") {
    fm.tags = data.tags.split(",").map((t) => t.trim());
  }

  if (data.draft !== undefined) {
    fm.draft = Boolean(data.draft);
  }

  if (typeof data.layout === "string") {
    fm.layout = data.layout;
  }

  for (const [key, value] of Object.entries(data)) {
    if (!["title", "date", "tags", "draft", "layout"].includes(key)) {
      fm[key] = value;
    }
  }

  return fm;
}

import { marked, type TokenizerAndRendererExtension } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";

const highlightExtension = markedHighlight({
  langPrefix: "hljs language-",
  highlight(code: string, lang: string) {
    if (lang && hljs.getLanguage(lang)) {
      return hljs.highlight(code, { language: lang }).value;
    }
    return code;
  },
});

marked.use(highlightExtension);

export function renderMarkdown(markdown: string): string {
  return marked.parse(markdown, { async: false }) as string;
}

import Handlebars from "handlebars";
import path from "node:path";
import fs from "node:fs";

export class Renderer {
  private partialsDir: string;
  private layoutsDir: string;
  private pagesDir: string;

  constructor(templateDir: string) {
    this.partialsDir = path.join(templateDir, "partials");
    this.layoutsDir = path.join(templateDir, "layouts");
    this.pagesDir = path.join(templateDir, "pages");
  }

  registerPartials(): void {
    if (!fs.existsSync(this.partialsDir)) return;
    for (const file of fs.readdirSync(this.partialsDir)) {
      if (!file.endsWith(".hbs") && !file.endsWith(".handlebars")) continue;
      const name = path.basename(file, path.extname(file));
      const content = fs.readFileSync(path.join(this.partialsDir, file), "utf-8");
      Handlebars.registerPartial(name, content);
    }
  }

  renderPage(templateName: string, data: Record<string, unknown>): string {
    const pagePath = path.join(this.pagesDir, `${templateName}.hbs`);
    if (!fs.existsSync(pagePath)) {
      throw new Error(`Page template not found: ${pagePath}`);
    }
    const pageSrc = fs.readFileSync(pagePath, "utf-8");
    const template = Handlebars.compile(pageSrc);
    const body = template(data);

    const layout = (data.layout as string) || "default";
    const layoutPath = path.join(this.layoutsDir, `${layout}.hbs`);
    if (fs.existsSync(layoutPath)) {
      const layoutSrc = fs.readFileSync(layoutPath, "utf-8");
      const layoutTemplate = Handlebars.compile(layoutSrc);
      return layoutTemplate({ ...data, body });
    }

    return body;
  }

  renderString(template: string, data: Record<string, unknown>): string {
    const compiled = Handlebars.compile(template);
    return compiled(data);
  }
}

import type { Frontmatter } from "./frontmatter.js";

export interface TagIndex {
  tag: string;
  posts: Frontmatter[];
}

export function buildTagIndex(postFms: Frontmatter[]): TagIndex[] {
  const map = new Map<string, Frontmatter[]>();
  for (const fm of postFms) {
    if (!fm.tags) continue;
    for (const tag of fm.tags) {
      const list = map.get(tag) ?? [];
      list.push(fm);
      map.set(tag, list);
    }
  }

  const indices: TagIndex[] = [];
  for (const [tag, posts] of map) {
    posts.sort((a, b) => (b.date ?? "").localeCompare(a.date ?? ""));
    indices.push({ tag, posts });
  }
  indices.sort((a, b) => a.tag.localeCompare(b.tag));
  return indices;
}

import type { Frontmatter } from "./frontmatter.js";

interface RSSOptions {
  title: string;
  description: string;
  siteUrl: string;
  posts: Frontmatter[];
}

export function generateRSS(opts: RSSOptions): string {
  const { title, description, siteUrl, posts } = opts;
  const items = posts
    .filter((p) => !p.draft)
    .map((p) => {
      const url = `${siteUrl}/${p.slug || ""}`;
      return `<item>
      <title><![CDATA[${escapeXML(p.title)}]]></title>
      <link>${escapeXML(url)}</link>
      <guid isPermaLink="true">${escapeXML(url)}</guid>
      <pubDate>${p.date ? new Date(p.date).toUTCString() : ""}</pubDate>
      ${(p.tags ?? []).map((t) => `<category>${escapeXML(t)}</category>`).join("\n      ")}
    </item>`;
    })
    .join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXML(title)}</title>
    <description>${escapeXML(description)}</description>
    <link>${escapeXML(siteUrl)}</link>
    <atom:link href="${escapeXML(siteUrl)}/feed.xml" rel="self" type="application/rss+xml"/>
    ${items}
  </channel>
</rss>`;
}

function escapeXML(str: string): string {
  return str
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

import path from "node:path";
import fs from "node:fs";
import { parseFrontmatter } from "./frontmatter.js";
import { renderMarkdown } from "./markdown.js";
import { Renderer } from "./renderer.js";
import { buildTagIndex } from "./tags.js";
import { generateRSS } from "./rss.js";
import type { Frontmatter } from "./frontmatter.js";

export interface SiteConfig {
  sourceDir: string;
  templateDir: string;
  outputDir: string;
  siteTitle?: string;
  siteDescription?: string;
  siteUrl?: string;
}

export interface Page {
  frontmatter: Frontmatter;
  html: string;
  path: string;
}

export async function buildSite(config: SiteConfig): Promise<Page[]> {
  const { sourceDir, templateDir, outputDir, siteTitle, siteDescription, siteUrl } = config;

  fs.mkdirSync(outputDir, { recursive: true });

  const renderer = new Renderer(templateDir);
  renderer.registerPartials();

  const mdFiles = collectMarkdownFiles(sourceDir);
  const parsed = mdFiles.map((f) => {
    const raw = fs.readFileSync(f, "utf-8");
    const { frontmatter, content } = parseFrontmatter(raw);
    const slug = frontmatter.slug || path.basename(f, path.extname(f));
    return { frontmatter: { ...frontmatter, slug }, content, sourcePath: f, slug };
  });

  const pages: Page[] = [];

  for (const entry of parsed) {
    if (entry.frontmatter.draft) continue;

    const bodyHtml = renderMarkdown(entry.content);
    const pageHtml = renderer.renderPage("post", {
      ...entry.frontmatter,
      body: bodyHtml,
      layout: entry.frontmatter.layout,
      siteTitle: siteTitle ?? "My Site",
    });

    const outPath = path.join(outputDir, `${entry.slug}.html`);
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, pageHtml);

    pages.push({ frontmatter: entry.frontmatter, html: pageHtml, path: outPath });
  }

  const published = pages
    .map((p) => p.frontmatter)
    .sort((a, b) => (b.date ?? "").localeCompare(a.date ?? ""));

  if (published.length > 0) {
    const indexHtml = renderer.renderPage("index", {
      posts: published,
      siteTitle: siteTitle ?? "My Site",
      layout: "default",
    });
    fs.writeFileSync(path.join(outputDir, "index.html"), indexHtml);

    const tags = buildTagIndex(published);
    const tagsDir = path.join(outputDir, "tags");
    fs.mkdirSync(tagsDir, { recursive: true });

    for (const { tag, posts } of tags) {
      const tagHtml = renderer.renderPage("tag", {
        tag,
        posts,
        siteTitle: siteTitle ?? "My Site",
        layout: "default",
      });
      fs.writeFileSync(path.join(tagsDir, `${tag}.html`), tagHtml);
    }

    const tagsIndexHtml = renderer.renderPage("tags", {
      tags,
      siteTitle: siteTitle ?? "My Site",
      layout: "default",
    });
    fs.writeFileSync(path.join(outputDir, "tags.html"), tagsIndexHtml);
  }

  if (siteUrl) {
    const feed = generateRSS({
      title: siteTitle ?? "My Site",
      description: siteDescription ?? "",
      siteUrl,
      posts: published.map((p) => ({ ...p })),
    });
    fs.writeFileSync(path.join(outputDir, "feed.xml"), feed);
  }

  copyStaticAssets(sourceDir, outputDir);

  return pages;
}

function collectMarkdownFiles(dir: string): string[] {
  const files: string[] = [];
  if (!fs.existsSync(dir)) return files;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...collectMarkdownFiles(full));
    } else if (entry.name.endsWith(".md")) {
      files.push(full);
    }
  }
  return files;
}

function copyStaticAssets(sourceDir: string, outputDir: string): void {
  for (const entry of fs.readdirSync(sourceDir, { withFileTypes: true })) {
    const src = path.join(sourceDir, entry.name);
    if (entry.isDirectory()) continue;
    if (entry.name.endsWith(".md")) continue;
    const dst = path.join(outputDir, entry.name);
    fs.copyFileSync(src, dst);
  }
}

import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import { WebSocketServer } from "ws";
import chokidar from "chokidar";
import { buildSite } from "./site.js";
import type { SiteConfig } from "./site.js";

const RELOAD_SCRIPT = `
<script>
(function(){
  var socket = new WebSocket('ws://' + location.host);
  socket.onmessage = function(msg) {
    if (msg.data === 'reload') location.reload();
  };
})();
</script>
`;

export function startDevServer(config: SiteConfig, port: number = 8080): http.Server {
  const wss = new WebSocketServer({ noServer: true });

  const clients = new Set<import("ws").WebSocket>();
  wss.on("connection", (ws) => {
    clients.add(ws);
    ws.on("close", () => clients.delete(ws));
  });

  function reloadAll() {
    for (const ws of clients) {
      ws.send("reload");
    }
  }

  const inferredRenderer = await import("./renderer.js");

  const server = http.createServer((req, res) => {
    const outDir = config.outputDir;
    const url = req.url === "/" ? "/index.html" : req.url ?? "/index.html";
    const filePath = path.join(outDir, url);

    if (!fs.existsSync(filePath)) {
      res.writeHead(404);
      res.end("Not Found");
      return;
    }

    let content = fs.readFileSync(filePath, "utf-8");
    if (filePath.endsWith(".html")) {
      content = content.replace("</body>", RELOAD_SCRIPT + "</body>");
    }

    const mimeTypes: Record<string, string> = {
      ".html": "text/html",
      ".css": "text/css",
      ".js": "application/javascript",
      ".xml": "application/xml",
      ".png": "image/png",
      ".jpg": "image/jpeg",
      ".svg": "image/svg+xml",
    };
    const ext = path.extname(filePath);
    res.writeHead(200, { "Content-Type": mimeTypes[ext] ?? "text/plain" });
    res.end(content);
  });

  let rebuildTimeout: ReturnType<typeof setTimeout>;
  const watcher = chokidar.watch([config.sourceDir, config.templateDir], {
    ignoreInitial: true,
  });

  watcher.on("all", (_event, _filePath) => {
    clearTimeout(rebuildTimeout);
    rebuildTimeout = setTimeout(async () => {
      try {
        await buildSite(config);
        reloadAll();
      } catch (e) {
        console.error("Build error:", e);
      }
    }, 200);
  });

  server.on("upgrade", (req, socket, head) => {
    wss.handleUpgrade(req, socket, head, (ws) => {
      wss.emit("connection", ws, req);
    });
  });

  server.listen(port);
  return server;
}
